  'fa-ellipsis-vertical': '⋮',
  'fa-circle-check': '✓',
  'fa-circle-exclamation': '!',
  'fa-bell-slash': '○',
  'fa-chevron-left': '‹',
  'fa-chevron-right': '›',
  'fa-xmark': '×',
  'fa-magnifying-glass': '⌕',
  'fa-cloud-arrow-up': '↑',
  'fa-image': '▧',
