  'fa-download': '↓',
  'fa-upload': '↑',
  'fa-refresh': '↻',
  'fa-arrows-rotate': '↻',
  'fa-house': '⌂',
  'fa-chart-line': '↗',
  'fa-database': '◉',
  'fa-gear': '⚙',
  'fa-cog': '⚙',
  'fa-camera-retro': '◉',
  'fa-circle-xmark': '×',
  'fa-triangle-exclamation': '!',
  'fa-circle-question': '?',
  'fa-info': 'i',
  'fa-eye': '◉',
